private GUPPricingAttributeTmp getDuplicatePricingAttribute(GUPPricingAttributeTmp _priceAttributes)
{

    Map pricingAttributeCountMap = new Map(Types::String, Types::Integer);
    Map pricingAttributeObjectListMap = new Map(Types::String, Types::AnyType);
    while select * from _priceAttributes
    {
        // We don't check duplicate for customer generated attributes.
        if (_priceAttributes.TypeName != "")
        {
            continue;
        }

        str nameKey = _priceAttributes.AttributeName; // + "_" + _priceAttributes.Source;
        if (!pricingAttributeCountMap.exists(nameKey))
        {
            pricingAttributeCountMap.insert(nameKey, 1);

            List attributeList = new List(Types::AnyType);
            attributeList.addEnd(_priceAttributes);
            pricingAttributeObjectListMap.insert(nameKey, attributeList);
        }
        else
        {
            pricingAttributeCountMap.insert(nameKey, pricingAttributeCountMap.lookup(nameKey) + 1);

            List attributeList = pricingAttributeObjectListMap.lookup(nameKey);
            attributeList.addEnd(_priceAttributes);
        }
    }

    int cnt = 1;
    GUPPricingAttributeTmp duplicate;
    MapEnumerator enumrator = pricingAttributeObjectListMap.getEnumerator();

    while (enumrator.moveNext())
    {
        List attributeList = enumrator.currentValue();
        /*if (attributeList.elements() == 1)
        {
            continue;
        }*/

        ListEnumerator listEnumrator = attributeList.getEnumerator();
        while (listEnumrator.moveNext())
        {
            GUPPricingAttributeTmp attr = listEnumrator.current();

            duplicate.Id = cnt;
            duplicate.AttributeName = attr.AttributeName;
            duplicate.PriceAttributeClassId = attr.PriceAttributeClassId;
            duplicate.TypeName = attr.TypeName;
            duplicate.ProviderClassId = attr.ProviderClassId;
            duplicate.Level = attr.Level;
            duplicate.Source = attr.Source;
            duplicate.PriceAttributeClassName = attr.PriceAttributeClassName;
            duplicate.insert();

            cnt ++;
        }
    }
    info(strFmt("Count: %1", cnt));
    return duplicate;
}

private str getNameKey(str name, str className)
{
    return name + "_" + className;
}

