public void executeQuery()
{
    Query q = GUPPricingAttributeTmp_ds.query();
    QueryRun qr = new SysQueryRun(q);
    while (qr.next())
    {
        GUPPricingAttributeTmp table1 = qr.get(tableNum(GUPPricingAttributeTmp));
        GUPPricingAttributeDuplicateClassRemind table2 = qr.get(tableNum(GUPPricingAttributeDuplicateClassRemind));
    }
    super();
}

public display str displayAttributeTable(GUPPricingAttributeTmp _tmp)
{
    DictClass dictClass = new DictClass(_tmp.PriceAttributeClassId);
    GUPIPricingAttribute attr = dictClass.makeObject();
    return attr.getQueryBuilderDatasourceIdentifier();
}

public display str displayAttributeField(GUPPricingAttributeTmp _tmp)
{
    DictClass dictClass = new DictClass(_tmp.PriceAttributeClassId);

    Object obj = dictClass.getAttribute('GUPPricingAttributeFieldsDiscoveryAttribute');

    if (obj != null)
    {
        GUPPricingAttributeFieldsDiscoveryAttribute attribute =
        (dictClass.getAttribute('GUPPricingAttributeFieldsDiscoveryAttribute') as GUPPricingAttributeFieldsDiscoveryAttribute);
        str fieldName = attribute.parmFieldName();
        return fieldName;
    }
    else 
    {
        return "[Not Set]";
    }

}

public display str displayAttributeType(GUPPricingAttributeTmp _tmp)
{
    DictClass dictClass = new DictClass(_tmp.PriceAttributeClassId);
    GUPIPricingAttribute attr = dictClass.makeObject();
    return enum2Symbol(enumNum(AttributeDataType), attr.getDataType());
}
